from datetime import datetime, timezone
import json

ACTIVITY_DEFS = [
    # (event_id, summary_key,           label)
    (1,  "child_processes",        "Child processes created"),
    (3,  "network_connections",    "Network connections"),
    (11, "files_created",          "Files created"),
    (13, "registry_modifications", "Registry modifications"),
    (22, "dns_queries",            "DNS queries"),
]

EVENT_TO_SUMMARY_KEY = {eid: key   for eid, key, _     in ACTIVITY_DEFS}
EVENT_TO_LABEL       = {eid: label for eid, _,   label in ACTIVITY_DEFS}


def clean(value):
    if value is None or value == "":
        return "Not available"

    value = str(value).strip()
    value = value.replace("|", r"\|")
    value = value.replace("\r", " ").replace("\n", " ")
    return value


def code(value):
    text = clean(value)

    if text == "Not available":
        return text

    if "`" in text:
        return f"`` {text} ``"

    return f"`{text}`"


def to_int(value, default=0):
    try:
        return int(value)
    except (TypeError, ValueError):
        return default


def process_name(image):
    if not image:
        return "Unknown"

    return str(image).replace("\\", "/").rstrip("/").split("/")[-1]


def format_timestamp(event):
    timestamp = event.get("UtcTime") or event.get("_time")

    if not timestamp:
        return "Unknown"

    return clean(timestamp)


def format_activity(event_id, event):

    if event_id == 1:
        evidence = (
            f"Created: {code(event.get('Image'))}; "
            f"Command: {code(event.get('CommandLine'))}"
        )
        actor = process_name(event.get("ParentImage"))

    elif event_id == 3:
        destination = (
            f"{clean(event.get('DestinationIp'))}:"
            f"{clean(event.get('DestinationPort'))}"
        )
        evidence = f"Destination: {code(destination)} ({clean(event.get('Protocol'))})"
        actor = process_name(event.get("Image"))

    elif event_id == 11:
        evidence = f"Created file: {code(event.get('TargetFilename'))}"
        actor = process_name(event.get("Image"))

    elif event_id == 13:
        evidence = (
            f"Modified: {code(event.get('TargetObject'))}; "
            f"Data: {code(event.get('Details'))}"
        )
        actor = process_name(event.get("Image"))

    elif event_id == 22:
        evidence = (
            f"Queried: {code(event.get('QueryName'))}; "
            f"Results: {code(event.get('QueryResults'))}; "
            f"Status: {clean(event.get('QueryStatus'))}"
        )
        actor = process_name(event.get("Image"))

    else:
        return None

    return {
        "time":     format_timestamp(event),
        "activity": EVENT_TO_LABEL[event_id],
        "process":  actor,
        "evidence": evidence,
    }


def build_process_report(splunk_response, root_process_guid):

    if not isinstance(splunk_response, list):
        raise ValueError("Splunk results must be a list")

    if not root_process_guid:
        raise ValueError("Root ProcessGuid is required")

    root_process_guid = root_process_guid.strip().lower()

    summary = {key: 0 for _, key, _ in ACTIVITY_DEFS}
    activity_rows = []

    for event in splunk_response:

        event_id     = to_int(event.get("EventCode"))
        process_guid = str(event.get("ProcessGuid", "")).strip().lower()
        parent_guid  = str(event.get("ParentProcessGuid", "")).strip().lower()


        if event_id == 1:
            if parent_guid != root_process_guid:
                continue
        elif process_guid != root_process_guid:
            continue

        key = EVENT_TO_SUMMARY_KEY.get(event_id)
        if key is not None:
            summary[key] += 1

        activity = format_activity(event_id, event)
        if activity:
            activity_rows.append(activity)

    activity_rows.sort(key=lambda row: row["time"])


    summary_markdown = (
        "## 6. Process Activity Summary\n\n"
        "| Activity | Count |\n"
        "|---|---:|\n"
    )
    for _, key, label in ACTIVITY_DEFS:
        summary_markdown += f"| {label} | {summary[key]} |\n"


    activity_markdown = (
        "## 7. Correlated Process Activity\n\n"
        "| Time (UTC) | Activity | Process | Evidence |\n"
        "|---|---|---|---|\n"
    )
    if activity_rows:
        for row in activity_rows:
            activity_markdown += (
                f"| {row['time']} "
                f"| {row['activity']} "
                f"| `{clean(row['process'])}` "
                f"| {row['evidence']} |\n"
            )
    else:
        activity_markdown += (
            "| - | No matching activity | - | No matching events returned |\n"
        )

    return {
        "summary":       summary,
        "activity_rows": activity_rows,
        "markdown":      summary_markdown + "\n" + activity_markdown,
    }


raw = r"""$splunk.body"""

data   = [json.loads(line) for line in raw.splitlines() if line.strip()]
events = [row["result"] for row in data if "result" in row]

report = build_process_report(
    splunk_response=events,
    root_process_guid="$exec.all_fields.full_log.win.eventdata.processGuid",
)

print(report["markdown"])

import ast
import re
import json
from datetime import datetime, timezone


TAGS = ["wazuh", "sysmon", "windows", "temp-execution", "virustotal" ]
TLP = 2
PAP = 2


def parse(raw):
    s = re.sub(r'\b(U|u)ndefined\b', 'None', str(raw))
    return ast.literal_eval(s)

def get_nested(data, *keys, default=None):
    for key in keys:
        if not isinstance(data, dict):
            return default
        data = data.get(key)

        if data is None:
            return default

    return data

def display(value):
    return str(value) if value is not None else "Not available"

def code(value):
    text = display(value)

    if text == "Not available":
        return text

    if "`" in text:           
        return f"`` {text} ``"

    return f"`{text}`"


def format_timestamp(value):
    if value is None:
        return None
    try:
        return datetime.fromtimestamp(
            int(value),
            tz=timezone.utc
        ).strftime("%Y-%m-%d %H:%M:%S UTC")
    except (ValueError, TypeError, OverflowError, OSError):
        return None


def extract_wazuh(wazuh):
    event = get_nested(
        wazuh, "data", "win", "eventdata",
        default={}
    )

    agent = wazuh.get("agent", {}) or {}
    rule = wazuh.get("rule", {}) or {}

    return {
        # Execution details
        "image": event.get("image"),
        "command_line": event.get("commandLine"),
        "current_directory": event.get("currentDirectory"),
        "username": event.get("user"),
        "logon_id": event.get("logonId"),
        "terminal_session": event.get("terminalSessionId"),
        "integrity_level": event.get("integrityLevel"),
        "process_id": event.get("processId"),
        "process_guid": event.get("processGuid"),
        "parent_image": event.get("parentImage"),
        "parent_process_id": event.get("parentProcessId"),
        "parent_command_line": event.get("parentCommandLine"),

        # Endpoint details
        "agent_id": agent.get("id"),
        "agent_name": agent.get("name"),
        "agent_ip": agent.get("ip"),
        "manager_name": get_nested(wazuh, "manager", "name"),

        # Detection details
        "alert_id": wazuh.get("id"),
        "rule_id": rule.get("id"),
        "rule_level": rule.get("level"),
    }


def normalize_virustotal(vt_response, sha256):
    http_status = int(vt_response.get("status"))
    body = vt_response.get("body") or {}

    result = {
        "status": "failed",
        "error": None,
        "attributes": {},
        "stats": {},
        "malicious": None,
        "suspicious": None,
        "reputation": None,
        "first_submission": None,
        "last_analysis": None,
        "file_id": None,
        "report_link": None,
    }

    if not isinstance(body, dict):
        body = {}

    if http_status == 404:
        result["status"] = "not_found"
        result["error"] = get_nested(
            body, "error", "message",
            default="File hash not found in VirusTotal."
        )
        return result

    if http_status != 200:
        result["status"] = "failed"
        result["error"] = get_nested(
            body, "error", "message",
            default=f"VirusTotal request failed. HTTP status: {http_status}"
        )
        return result

    data = body.get("data") or {}

    if not isinstance(data, dict) or not data:
        result["status"] = "invalid_response"
        result["error"] = "HTTP 200 received, but file report data was missing."
        return result

    attributes = data.get("attributes") or {}

    if not isinstance(attributes, dict):
        attributes = {}

    result["attributes"] = attributes
    result["file_id"] = data.get("id") or sha256


    if data.get("type") == "file" and result["file_id"]:
        result["report_link"] = (
            f"https://www.virustotal.com/gui/file/{result['file_id']}"
        )

    result["reputation"] = attributes.get("reputation")

    result["first_submission"] = format_timestamp(
        attributes.get("first_submission_date")
    )

    result["last_analysis"] = format_timestamp(
        attributes.get("last_analysis_date")
    )

    stats = attributes.get("last_analysis_stats")

    if not isinstance(stats, dict) or not {
        "malicious", "suspicious"
    }.issubset(stats):
        result["status"] = "record_without_stats"
        result["error"] = (
            "VirusTotal returned a file record, "
            "but analysis statistics were unavailable."
        )
        return result

    result["stats"] = stats
    result["malicious"] = stats.get("malicious")
    result["suspicious"] = stats.get("suspicious")
    result["status"] = "completed"

    return result


def build_file_info(sha256, vt_info):
    attributes = vt_info["attributes"]

    file_type = (
        attributes.get("type_description")
        or get_nested(attributes, "detectiteasy", "filetype")
    )

    return {
        "sha256": sha256,
        "sha1": attributes.get("sha1"),
        "md5": attributes.get("md5"),
        "file_type": file_type,
    }


def build_observables(sha256, wazuh_info):
    observables = []

    if sha256:
        observables.append({
            "dataType": "hash",
            "data": [sha256],
            "tlp": TLP,
            "tags": ["sha256"],
            "message": "Executable SHA256",
            "ioc": False,
        })

    if wazuh_info["image"]:
        observables.append({
            "dataType": "filename",
            "data": [wazuh_info["image"]],
            "tlp": TLP,
            "message": "Executable Image Path",
            "ioc": False,
        })

    if wazuh_info["agent_ip"]:
        observables.append({
            "dataType": "ip",
            "data": [wazuh_info["agent_ip"]],
            "tlp": TLP,
            "tags": ["endpoint", "agent"],
            "message": "Affected Endpoint IP",
            "ioc": False,
        })

    return observables



def build_description(wazuh_info, file_info, vt_info, process_activity_md=""):

    v = file_info
    w = wazuh_info

    vt_section = f"""## 5. VirusTotal Analysis
- Enrichment Status: {display(vt_info['status'])}
"""

    if vt_info["status"] == "completed":
        vt_section += f"""- Malicious Detections: {display(vt_info['malicious'])}
- Suspicious Detections: {display(vt_info['suspicious'])}
- Reputation: {display(vt_info['reputation'])}
- First Submission: {code(vt_info['first_submission'])}
- Last Analysis: {code(vt_info['last_analysis'])}
"""

    else:
        vt_section += f"""- Enrichment Error: {display(vt_info['error'])}
"""

    if vt_info["report_link"]:
        vt_section += (
            f"- VirusTotal Report: "
            f"[View on VirusTotal]({vt_info['report_link']})\n"
        )

    # Build main description
    description = f"""## 1. Detection Summary
- Detection: Executable launched from a Windows Temp directory or its subdirectories
- Detection Source: Wazuh
- Wazuh Rule ID: {display(w['rule_id'])}
- Wazuh Rule Level: {display(w['rule_level'])}
- Wazuh Alert ID: {display(w['alert_id'])}

## 2. Execution Details
- Image: {code(w['image'])}
- CommandLine: {code(w['command_line'])}
- WorkingDirectory: {code(w['current_directory'])}
- User: {code(w['username'])}
- LogonId: {display(w['logon_id'])}
- Terminal Session: {display(w['terminal_session'])}
- Integrity Level: {display(w['integrity_level'])}
- Process ID: {display(w['process_id'])}
- Process GUID: {code(w['process_guid'])}
- Parent Image: {code(w['parent_image'])}
- Parent Process ID: {display(w['parent_process_id'])}
- Parent CommandLine: {code(w['parent_command_line'])}

## 3. Affected Endpoint
- Agent ID: {display(w['agent_id'])}
- Hostname: {code(w['agent_name'])}
- Endpoint IP: {code(w['agent_ip'])}
- Manager: {code(w['manager_name'])}

## 4. File Information
- SHA256: {code(v['sha256'])}
- SHA1: {code(v['sha1'])}
- MD5: {code(v['md5'])}
- File Type: {display(v['file_type'])}

{vt_section}
"""

    if process_activity_md and process_activity_md.strip():
        description += f"""
{process_activity_md}
"""

    return description


def compute_severity(vt_info):
    status = vt_info.get("status")

    malicious = vt_info.get("malicious")
    suspicious = vt_info.get("suspicious")

    if status != "completed":
        return 2

    if malicious is None or suspicious is None:
        return 2

    try:
        malicious = int(malicious)
        suspicious = int(suspicious)
    except (ValueError, TypeError):
        return 2

    if malicious < 0 or suspicious < 0:
        return 2

    if malicious >= 8:
        return 3

    if malicious > 0 or suspicious > 0:
        return 2

    return 2


wazuh_raw = ast.literal_eval(r"""{{ $exec.all_fields }}""")
vt = parse(r"""{{ $vt }}""")
